/**
 * HTTP entry: assigns a request id to every incoming request, applies per-client rate limiting,
 * and hands what survives to the router. This is where the request id is born.
 */
import { randomUUID, createHash } from "node:crypto";
import { Router, type RouteRequest, type RouteResponse } from "./router.ts";
import { JobQueue } from "../jobs/JobQueue.ts";
import { RateLimiter, type RateLimitOptions } from "./RateLimiter.ts";
import { AppLogger, type Sink } from "../platform/logging/AppLogger.ts";

export interface IncomingRequest {
  readonly method: RouteRequest["method"];
  readonly path: string;
  readonly headers: Record<string, string | undefined>;
  readonly body?: unknown;
}

const DEFAULT_RATE_LIMIT: RateLimitOptions = { limit: 60, windowMs: 60_000 };

/** Callers without an `x-client-id` share this one window; see the T-4 plan for why that is accepted. */
const ANONYMOUS_CLIENT = "anonymous";

const MAX_CLIENT_ID_LENGTH = 200;

export function createApp(
  queue: JobQueue = new JobQueue(),
  sink?: Sink,
  rateLimit: RateLimitOptions = DEFAULT_RATE_LIMIT,
): { handle(req: IncomingRequest): Promise<RouteResponse> } {
  const router = new Router(sink)
    .add("GET", "/health", (_req, log) => {
      log.info("health check");
      return { status: 200, body: { ok: true } };
    })
    .add("POST", "/reports", (req, log) => {
      const id = queue.enqueue({ kind: "report", payload: req.body }, { requestId: req.requestId });
      log.info("report queued", { jobId: id });
      return { status: 202, body: { jobId: id } };
    });

  const limiter = new RateLimiter(rateLimit);

  return {
    async handle(req: IncomingRequest): Promise<RouteResponse> {
      const requestId = resolveRequestId(req.headers["x-request-id"]);
      const clientId = resolveClientId(req.headers["x-client-id"]);
      const verdict = limiter.check(clientId);

      if (!verdict.allowed) {
        // The router is never reached, so this path builds its own logger to keep every line under a request id.
        AppLogger.withRequestId(requestId, sink).warn("rate limit exceeded", {
          clientIdHash: hashClientId(clientId),
          limit: verdict.limit,
          retryAfterSeconds: verdict.retryAfterSeconds,
        });
        return { status: 429, body: { error: "rate limit exceeded" } };
      }

      return router.dispatch({ method: req.method, path: req.path, requestId, body: req.body });
    },
  };
}

/** A blank header is as good as absent: AppLogger refuses an empty request id, and the 429 path logs before dispatch. */
function resolveRequestId(header: string | undefined): string {
  const trimmed = header?.trim() ?? "";
  return trimmed === "" ? randomUUID() : trimmed;
}

/** One place decides what "the same client" means; the limiter itself treats the result as opaque. */
function resolveClientId(header: string | undefined): string {
  const normalized = (header ?? "").trim().toLowerCase().slice(0, MAX_CLIENT_ID_LENGTH);
  return normalized === "" ? ANONYMOUS_CLIENT : normalized;
}

/** The client id is caller-controlled and AppLogger's redaction is key- and shape-based, so it never reaches a log line verbatim. */
function hashClientId(clientId: string): string {
  return createHash("sha256").update(clientId).digest("hex").slice(0, 12);
}
